(4272301, 615652, 41914, '<td valign="top">OH boy, your going to get slammed for this. I did this in the other colors chalenge and got hammered. I applaud your desire to push limits good job</td>', 'OH boy, your going to get slammed for this. I did this in the other colors chalenge and got hammered. I applaud your desire to push limits good job', '2007-11-28 00:04:54.000000', NULL, 1),
(4272309, 617213, 57202, '<td valign="top">Wonderfully creative idea!  Not only that, but the colors are extremely vivid and the details are tack-sharp.  Great shot! :)</td>', 'Wonderfully creative idea!  Not only that, but the colors are extremely vivid and the details are tack-sharp.  Great shot! :)', '2007-11-28 00:05:30.000000', NULL, 1),
