(4273788, 616571, 66267, '<td valign="top">nice concept but too dark.</td>', 'nice concept but too dark.', '2007-11-28 13:02:49.000000', NULL, 1),
(4273789, 615830, 80912, '<td valign="top">Interesting setup. Unfortunately (at least on my monitor) the purple looks more like brown.</td>', 'Interesting setup. Unfortunately (at least on my monitor) the purple looks more like brown.', '2007-11-28 13:03:00.000000', NULL, 1),
