(4273798, 617292, 52472, '<td valign="top">We''ve seen a lot of them, but it''s definitively one of the nicer ones. The only little flaw are the reflections on the top.</td>', 'We''ve seen a lot of them, but it''s definitively one of the nicer ones. The only little flaw are the reflections on the top.', '2007-11-28 13:05:20.000000', NULL, 1),
(4273804, 616885, 52472, '<td valign="top">Great composition and DOF, very appetizing!</td>', 'Great composition and DOF, very appetizing!', '2007-11-28 13:06:46.000000', NULL, 1),
