(4273821, 617006, 80912, '<td valign="top">Nice. I just wish there weren''t all the puddles on the tabletop.</td>', 'Nice. I just wish there weren''t all the puddles on the tabletop.', '2007-11-28 13:11:01.000000', NULL, 1),
(4273834, 617383, 52472, '<td valign="top">The composition is absolutely fantastic! Lots of triangles, nice colours, very appealing. If there''s one flaw, then it''s the narrow DOF. 10 anyway.</td>', 'The composition is absolutely fantastic! Lots of triangles, nice colours, very appealing. If there''s one flaw, then it''s the narrow DOF. 10 anyway.', '2007-11-28 13:16:18.000000', NULL, 1),
