(4282843, 616769, 83313, '<td valign="top">The colors on the blocks seem a little washed out. Maybe reflecting off the red too much, perhaps. A different angle may heave had more punch. Sorry, this one is just not doing it for me, but I can see some good ideas and effort.</td>', 'The colors on the blocks seem a little washed out. Maybe reflecting off the red too much, perhaps. A different angle may heave had more punch. Sorry, this one is just not doing it for me, but I can see some good ideas and effort.', '2007-12-02 13:42:52.000000', NULL, 1),
(4282854, 616734, 83313, '<td valign="top">To be honest, at first glance, I thought it was a sex toy. But I''ve seen these at the store. Neat idea. Some noise or artifacts of JPEG compression are showing in the yellow backdrop.</td>', 'To be honest, at first glance, I thought it was a sex toy. But I''ve seen these at the store. Neat idea. Some noise or artifacts of JPEG compression are showing in the yellow backdrop.', '2007-12-02 13:46:29.000000', NULL, 1),
(4282858, 617350, 83313, '<td valign="top">Nice take on a commonly seen item. I assume you used a filter to get this effect? How did you get both lit at once within the challenge rules?</td>', 'Nice take on a commonly seen item. I assume you used a filter to get this effect? How did you get both lit at once within the challenge rules?', '2007-12-02 13:48:22.000000', NULL, 1),
(4282860, 617351, 83313, '<td valign="top">Sorry, this has no impact for me. Colors seem a little washed out.</td>', 'Sorry, this has no impact for me. Colors seem a little washed out.', '2007-12-02 13:49:32.000000', NULL, 1),
(4282862, 617231, 83313, '<td valign="top">Neat looking.</td>', 'Neat looking.', '2007-12-02 13:50:07.000000', NULL, 1),
