(4283370, 616901, 23002, '<td valign="top">Great concept! 8</td>', 'Great concept! 8', '2007-12-02 18:24:24.000000', NULL, 1),
(4283373, 616205, 23002, '<td valign="top">great texture in the rust.  the green background seems a bit to "created" to me.  (like it was a piece of green paper held behind)</td>', 'great texture in the rust.  the green background seems a bit to "created" to me.  (like it was a piece of green paper held behind)', '2007-12-02 18:25:38.000000', NULL, 1),
