(4283378, 616912, 23002, '<td valign="top">great idea.</td>', 'great idea.', '2007-12-02 18:27:09.000000', NULL, 1),
(4283386, 617446, 23002, '<td valign="top">I think that the concept would have been better without applying the nasty green colour cast to the whole image.  It makes her look dead. :(</td>', 'I think that the concept would have been better without applying the nasty green colour cast to the whole image.  It makes her look dead. :(', '2007-12-02 18:29:09.000000', NULL, 1),
(4283391, 617466, 23002, '<td valign="top">butt?  I thought that was the top of the pepper?  Lighting is very harsh and the DOF is not great enough. Nice eye to see the colours though.</td>', 'butt?  I thought that was the top of the pepper?  Lighting is very harsh and the DOF is not great enough. Nice eye to see the colours though.', '2007-12-02 18:30:29.000000', NULL, 1),
(4283394, 615625, 23002, '<td valign="top">Interesting for basic colours.  I will give you the benefit of the doubt and a 6.</td>', 'Interesting for basic colours.  I will give you the benefit of the doubt and a 6.', '2007-12-02 18:31:29.000000', NULL, 1),
(4283435, 617293, 87190, '<td valign="top">Too much is out of focus, making it look like the picture is a victim of Bulls''-eye syndrome. The unfocused yellow at the bottom also draws away the viewer''s eye. A good cropping of that bottom stuff would be good. The focus on the flowers you DO have focused though is really nice. Red placed against blue makes them vibrate against each other but that''s what''s making the picture so vivid; it would be much more powerful without that yellow.</td>', 'Too much is out of focus, making it look like the picture is a victim of Bulls''-eye syndrome. The unfocused yellow at the bottom also draws away the viewer''s eye. A good cropping of that bottom stuff would be good. The focus on the flowers you DO have focused though is really nice. Red placed against blue makes them vibrate against each other but that''s what''s making the picture so vivid; it would be much more powerful without that yellow.', '2007-12-02 18:47:20.000000', NULL, 1),
(4283441, 617496, 87190, '<td valign="top">Wow it''s a painting (a picture I know, but it just looks so abstract)</td>', 'Wow it''s a painting (a picture I know, but it just looks so abstract)', '2007-12-02 18:48:53.000000', NULL, 1),
(4283445, 617470, 87190, '<td valign="top">Very beautiful contrast. The little bit that touches the bottom frame distracts the eye a bit I''m afraid.</td>', 'Very beautiful contrast. The little bit that touches the bottom frame distracts the eye a bit I''m afraid.', '2007-12-02 18:50:43.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4283447, 617320, 87190, '<td valign="top">A lot of red with not enough green to it; the background green is completely overpowered by the red.</td>', 'A lot of red with not enough green to it; the background green is completely overpowered by the red.', '2007-12-02 18:52:19.000000', NULL, 1),
