(4284681, 616199, 82817, '<td valign="top">For me the dark edge of the guitar doesn''t quite work. However I don''t think the complimentary colors need to be side by side. I lean toward the colors side by side but I am changing my tune here.</td>', 'For me the dark edge of the guitar doesn''t quite work. However I don''t think the complimentary colors need to be side by side. I lean toward the colors side by side but I am changing my tune here.', '2007-12-03 02:50:51.000000', NULL, 1),
(4284684, 615595, 82817, '<td valign="top">Complimentary in natural setting. I really like what you have captured here.</td>', 'Complimentary in natural setting. I really like what you have captured here.', '2007-12-03 02:52:36.000000', NULL, 1),
(4284686, 617428, 82817, '<td valign="top">This is a stretch for me to get the clarity of meeting the challenge. I do like the image very much.</td>', 'This is a stretch for me to get the clarity of meeting the challenge. I do like the image very much.', '2007-12-03 02:54:17.000000', NULL, 1),
(4284688, 616104, 82817, '<td valign="top">Wonderful colors.</td>', 'Wonderful colors.', '2007-12-03 02:54:56.000000', NULL, 1),
