INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4448153, 617097, 61651, '<td valign="top">Subtle, delicate, lovely.  Unfairly punished in the voting.</td>', 'Subtle, delicate, lovely.  Unfairly punished in the voting.', '2008-02-01 17:18:50.000000', NULL, 0),
(4448829, 617185, 61651, '<td valign="top">Complementary *and* rich - I like that there''s such a wide swath of grass for the eye to pass across to get to the barn, there''s an inviting expansiveness to this.</td>', 'Complementary *and* rich - I like that there''s such a wide swath of grass for the eye to pass across to get to the barn, there''s an inviting expansiveness to this.', '2008-02-01 21:01:41.000000', NULL, 0),
(4500404, 616374, 47483, '<td valign="top">i don''t know even I shall comment on any photo seeing that so many controversies going on. But just stopped by to say that I liked the photo. It has something which is not typical of DPC. Looks like a virgin photo untouched by post processing sin. Got me thinking soon you would be doing heavy post processing and this freshness would vaporise. <br/>Nice fresh one it is though.</td>', 'i don''t know even I shall comment on any photo seeing that so many controversies going on. But just stopped by to say that I liked the photo. It has something which is not typical of DPC. Looks like a virgin photo untouched by post processing sin. Got me thinking soon you would be doing heavy post processing and this freshness would vaporise. Nice fresh one it is though.', '2008-02-20 09:10:37.000000', NULL, 0),
(4544488, 617213, 90495, '<td valign="top">Contrast! I like. Nice work setting up all this, it''s certainly worth the effort.</td>', 'Contrast! I like. Nice work setting up all this, it''s certainly worth the effort.', '2008-03-07 00:20:10.000000', NULL, 0),
(4550294, 616374, 90495, '<td valign="top">Beautiful. Well captured image. <br/> <br/>I would have liked to see the sky darker but the challenge doesn''t permit it. Too bad.</td>', 'Beautiful. Well captured image.  I would have liked to see the sky darker but the challenge doesn''t permit it. Too bad.', '2008-03-09 16:06:21.000000', NULL, 0),
(4599659, 616675, 62787, '<td valign="top">Beautiful picture! Lovely and sharp, great DOF and fantastic colours. Way underrated, imo.</td>', 'Beautiful picture! Lovely and sharp, great DOF and fantastic colours. Way underrated, imo.', '2008-03-31 19:40:00.000000', NULL, 0),
(4648843, 616571, 91679, '<td valign="top">A bit out of focus and too dark</td>', 'A bit out of focus and too dark', '2008-04-19 14:00:57.000000', NULL, 0),
(4655271, 617334, 52549, '<td valign="top">It is indeed a nice tribute and I like it a lot. The complimentary colours are wonderful.<br/>Thanks for the kind words, I''m truly honoured.</td>', 'It is indeed a nice tribute and I like it a lot. The complimentary colours are wonderful.Thanks for the kind words, I''m truly honoured.', '2008-04-23 11:48:32.000000', NULL, 0),
(4703144, 617213, 43463, '<td valign="top">Love the bold hues of the oranges and blues in this composition. Very eye catching and the arrangement of elements is also pleasing to the eye. A ripple of orange splashes upon the deep blue ''ocean'' surface. Orange and pale blue seastars adorn this ocean inspired composition. Very lovely.</td>', 'Love the bold hues of the oranges and blues in this composition. Very eye catching and the arrangement of elements is also pleasing to the eye. A ripple of orange splashes upon the deep blue ''ocean'' surface. Orange and pale blue seastars adorn this ocean inspired composition. Very lovely.', '2008-05-14 23:22:32.000000', NULL, 0),
(4703651, 617213, 68586, '<td valign="top">Shez - you do these shots so well. Love the colours and layout.</td>', 'Shez - you do these shots so well. Love the colours and layout.', '2008-05-15 04:17:13.000000', NULL, 0),
(4714234, 616044, 82461, '<td valign="top">waves on fabric are superb...<br/> <br/>there seems shadow on last letter "e"..... if that can be avoided, the there would be only two complimentory colors in the pic... IMO....<br/> <br/>great idea...</td>', 'waves on fabric are superb... there seems shadow on last letter "e"..... if that can be avoided, the there would be only two complimentory colors in the pic... IMO.... great idea...', '2008-05-21 06:07:29.000000', NULL, 0),
(4714672, 616044, 48228, '<td valign="top">My first thought was a different language, which unsettled me a little. <br/>The idea is excellent, and I love the strong complimentary colors are bold and well placed. <br/>I am not sure why the voters did not mark this higher, as it is a well balanced image, and fits the challenge well.....<br/>I like the folds in the material, and also the crop.<br/></td>', 'My first thought was a different language, which unsettled me a little. The idea is excellent, and I love the strong complimentary colors are bold and well placed. I am not sure why the voters did not mark this higher, as it is a well balanced image, and fits the challenge well.....I like the folds in the material, and also the crop.', '2008-05-21 10:50:03.000000', NULL, 0),
(4717240, 616758, 48228, '<td valign="top">This is a great idea and love the strong composition, colors and the detail very much.....</td>', 'This is a great idea and love the strong composition, colors and the detail very much.....', '2008-05-22 10:32:39.000000', NULL, 0),
(4721093, 617257, 48228, '<td valign="top">This is so simple, but yet so well done, and so suits this challenge of complementary colors of purple and yellow. The lemon slice is excellent, and I love the textures of the water droplets on the glass. I also like the crop, as it suits the composition really well..... Excellent image and also an excellent title.....</td>', 'This is so simple, but yet so well done, and so suits this challenge of complementary colors of purple and yellow. The lemon slice is excellent, and I love the textures of the water droplets on the glass. I also like the crop, as it suits the composition really well..... Excellent image and also an excellent title.....', '2008-05-24 09:02:44.000000', NULL, 0),
(4721446, 617257, 49804, '<td valign="top">Really nice shot here, one thing I think people would have scored it even better for, would have been if the front of the glass had been in focus as well, really though an incredible shot, and very nicely done.</td>', 'Really nice shot here, one thing I think people would have scored it even better for, would have been if the front of the glass had been in focus as well, really though an incredible shot, and very nicely done.', '2008-05-24 14:06:55.000000', NULL, 0),
